sys_script_include.script:
var FirewallImportUtil = Class.create();
FirewallImportUtil.prototype = {
    initialize: function() {
    },

	/**The Import Multiple endpoint of the Import Set API accepts JSON in the following format:
     * {
     * records [
     * {"name" : "string", "values" : "1,2,3"},
     * {"name" : "string", "values" : "1,2,3"},
     * ]
     * }
     * runImportUtil returns an array of objects from the parsePayload function which in turn is then passed as records into the sendToImportSet function, which wraps that array of objects with records appended, as this is the expected format for the Import set API when calling Import Multiple.
     * **/

	_sendToImportSet: function(records, table) {
        try {
            var instanceUrl = gs.getProperty("glide.servlet.uri");
            var url = instanceUrl + "api/now/import/" + table + "/insertMultiple";

            var rm = new sn_ws.RESTMessageV2();
            rm.setHttpMethod("POST");
            rm.setEndpoint(url);
            rm.setRequestHeader("Content-Type", "application/json");

            var user = 'panorama_int_admin';
            var password = '0:Z>!y:52ty5FPtl]uph!$xDX1}o&_+9x;Qx[*i2';

            rm.setBasicAuth(user, password);

            var requestBody = {
                records: records
            };
            rm.setRequestBody(JSON.stringify(requestBody));

            var response = rm.execute();
            var status = response.getStatusCode();

            if (status != 200 && status != 201) {
                var err = "Import Set API call failed for table: " + table + " Status: " + status + " | Body: " + response.getBody();
                return {
					success: false,
					error: err
				};
            }
            gs.info("Panorama Import Set Creation: was successful for table: " + table + " Please inspect Transform Histories for more information.");
        } catch (ex) {
            gs.info(ex.message);
        }
    },

    type: 'FirewallImportUtil'
};
